def _dashed(code: str, dash: str) -> str:
    return dash.join(code[i : i + 4] for i in range(0, len(code), 4))


DASHES = {"en dash": "\u2013", "em dash": "\u2014", "figure dash": "\u2012", "minus sign": "\u2212", "spaced en dash": " \u2013 "}
